code.java:
public int getSum(int a, int b) {
    int result = 0, carry = 0;
    for (int i = 0; i < 32; i++) {
        int bitA = (a >> i) & 1;
        int bitB = (b >> i) & 1;
        int sum = bitA ^ bitB ^ carry;
        carry = (bitA & bitB) | (carry & (bitA ^ bitB));
        result |= (sum << i);
    }
    return result;
}

