code.java:
public int getSum(int a, int b) {
    while (b != 0) {
        int carry = (a & b) << 1;
        a = a ^ b;
        b = carry;
    }
    return a;
}

code.python:
def getSum(self, a: int, b: int) -> int:
    mask = 0xFFFFFFFF
    while (b & mask) != 0:
        carry = (a & b) << 1
        a = a ^ b
        b = carry
    a &= mask
    if a <= 0x7FFFFFFF:
        return a
    return ~(a ^ mask)
